import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"家人","description":"周易正义 - 家人","frontmatter":{"title":"家人","description":"周易正义 - 家人"},"headers":[],"relativePath":"zh/classics/zhengyi/037.md","filePath":"zh/classics/zhengyi/037.md"}'),l={name:"zh/classics/zhengyi/037.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>风火家人</p></blockquote><blockquote><p>卦辞：利女贞。</p></blockquote><blockquote><p>彖曰：家人，女正位乎内，男正位乎外。男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正。正家而天下定矣。</p></blockquote><h1 id="家人" tabindex="-1">家人 <a class="header-anchor" href="#家人" aria-label="Permalink to “家人”">​</a></h1><p>王弼：家人之义，各自脩一家之道，不能知家外他人之事也。统而论之，非元亨利君子之贞，故“利女贞”。其正在家内而巳。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“家人”者，卦名也。明家内之道，正一家之人，故谓之“家人”。“利女贞”者，既修家内之道，不能知家外他人之事。统而论之，非君子丈夫之正，故但言“利女贞”。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="家人-女正位乎内-谓二也。男正位乎外。-​" tabindex="-1">家人，女正位乎内，谓二也。男正位乎外。 ​ <a class="header-anchor" href="#家人-女正位乎内-谓二也。男正位乎外。-​" aria-label="Permalink to “家人，女正位乎内，谓二也。男正位乎外。 ​”">​</a></h3><p>王弼：谓五也。家人之义，以内为本，故先说女也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“《彖》曰”至“男正位乎外”。○正义曰：此因二、五得正以释“家人”之义，并明女贞之旨。家人之道，必须女主於内，男主於外，然后家道乃立。今此卦六二柔而得位，是女正位乎内也。九五刚而得位，是男正位乎外也。家人“以内为本，故先说女也”。</p><h3 id="男女正-天地之大义也。家人有严君焉。父母之谓也。父父、子子、兄兄、弟弟、夫夫、妇妇而家道正-正家而天下定矣。-​" tabindex="-1">男女正，天地之大义也。家人有严君焉。父母之谓也。父父、子子、兄兄、弟弟、夫夫、妇妇而家道正，正家而天下定矣。 ​ <a class="header-anchor" href="#男女正-天地之大义也。家人有严君焉。父母之谓也。父父、子子、兄兄、弟弟、夫夫、妇妇而家道正-正家而天下定矣。-​" aria-label="Permalink to “男女正，天地之大义也。家人有严君焉。父母之谓也。父父、子子、兄兄、弟弟、夫夫、妇妇而家道正，正家而天下定矣。 ​”">​</a></h3><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>“男女正”至“天下定矣”。○正义曰：“男女正天地之大义也”者，因正位之言，广明家人之义乃道均二仪，故曰“天地之大义也”。“家人有严君焉父母之谓”者，上明义均天地，此又言道齐邦国。父母一家之主，家人尊事，同於国有严君，故曰“家人有严君焉父母之谓”也。“父父、子子、兄兄、弟弟、夫夫、妇妇而家道正，正家而天下定矣”者，此叹美正家之功，可以定於天下，申成道齐邦国。既家有严君，即父不失父道，乃至妇不失妇道，尊卑有序，上下不失，而后为家道之正。各正其家，无家不正，即天下之治定矣。</p><h2 id="《象》曰-风自火出-家人。-​" tabindex="-1">《象》曰：风自火出，家人。 ​ <a class="header-anchor" href="#《象》曰-风自火出-家人。-​" aria-label="Permalink to “《象》曰：风自火出，家人。 ​”">​</a></h2><p>王弼：由内以相成炽也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：巽在离外，是风从火出。火出之初，因风方炽。火既炎盛，还复生风。内外相成，有似家人之义。故曰“风自火出家人”也。</p><h3 id="君子以言有物而行有恒。-​" tabindex="-1">君子以言有物而行有恒。 ​ <a class="header-anchor" href="#君子以言有物而行有恒。-​" aria-label="Permalink to “君子以言有物而行有恒。 ​”">​</a></h3><p>王弼：家人之道，脩於近小而不妄也。故君子以言必有物而口无择言，行必有恒而身无择行。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：物，事也。言必有事，即口无择言。行必有常，即身无择行。正家之义，修於近小。言之与行，君子枢机。出身加人，发迩化远，故举言行以为之诫。言既称物，而行称“恒”者，发言立行，皆须合於可常之事，互而相足也。</p><h2 id="初九-闲有家-悔亡。-​" tabindex="-1">初九：闲有家，悔亡。 ​ <a class="header-anchor" href="#初九-闲有家-悔亡。-​" aria-label="Permalink to “初九：闲有家，悔亡。 ​”">​</a></h2><p>王弼：凡教在初而法在始，家渎而后严之，志变而后治之，则“悔”矣。处家人之初，为家人之始，故宜必以“闲有家”，然后“悔亡”也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：治家之道，在初即须严正，立法防闲。若黩乱之后，方始治之，即有悔矣。初九处家人之初，能防闲有家，乃得“悔亡”，故曰“闲有家，悔亡”也。</p><h3 id="《象》曰-闲有家-志未变也。-​" tabindex="-1">《象》曰：“闲有家”，志未变也。 ​ <a class="header-anchor" href="#《象》曰-闲有家-志未变也。-​" aria-label="Permalink to “《象》曰：“闲有家”，志未变也。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志未变也”者，释在初防闲之义。所以在初防闲其家者，家人志未变黩也。</p><h2 id="六二-无攸遂-在中馈-贞吉。-​" tabindex="-1">六二：无攸遂，在中馈，贞吉。 ​ <a class="header-anchor" href="#六二-无攸遂-在中馈-贞吉。-​" aria-label="Permalink to “六二：无攸遂，在中馈，贞吉。 ​”">​</a></h2><p>王弼：居内处中，履得其位，以阴应阳，尽妇人之正，义无所必，遂职乎“中馈”，巽顺而巳，是以“贞吉”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：六二履中居位，以阴应阳，尽妇人之义也。妇人之道，巽顺为常，无所必遂。其所职主，在於家中馈食供祭而已，得妇人之正吉，故曰“无攸遂在中馈贞吉”也。</p><h3 id="《象》曰-六二之-吉-顺以巽也。-​" tabindex="-1">《象》曰：六二之“吉”，顺以巽也。 ​ <a class="header-anchor" href="#《象》曰-六二之-吉-顺以巽也。-​" aria-label="Permalink to “《象》曰：六二之“吉”，顺以巽也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：举爻位也。言“吉”者，明其以柔居中而得正位，故能顺以巽而获吉也。</p><h2 id="九三-家人嗃嗃-悔厉-吉。妇子嘻嘻-终吝。-​" tabindex="-1">九三：家人嗃嗃，悔厉，吉。妇子嘻嘻，终吝。 ​ <a class="header-anchor" href="#九三-家人嗃嗃-悔厉-吉。妇子嘻嘻-终吝。-​" aria-label="Permalink to “九三：家人嗃嗃，悔厉，吉。妇子嘻嘻，终吝。 ​”">​</a></h2><p>王弼：以阳处阳，刚严者也。处下体之极，为一家之长者也。行与其慢，宁过乎恭；家与其渎，宁过乎严。是以家人虽“嗃嗃悔厉”，犹得其道。“妇子嘻嘻”，乃失其节也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“嗃嗃”，严酷之意也。“嘻嘻”，喜笑之貌也。九三处下体之上，为一家之主，以阳处阳，行刚严之政，故“家人嗃嗃”。虽复嗃嗃伤猛，悔其酷厉，犹保其吉，故曰“悔厉吉”。若纵其妇子慢黩嘻嘻，喜笑而无节，则终有恨辱，故曰“妇子嘻嘻终吝”也。</p><h3 id="《象》曰-家人嗃嗃-未失也。-妇子嘻嘻-失家节也。-​" tabindex="-1">《象》曰：“家人嗃嗃”，未失也。“妇子嘻嘻”，失家节也。 ​ <a class="header-anchor" href="#《象》曰-家人嗃嗃-未失也。-妇子嘻嘻-失家节也。-​" aria-label="Permalink to “《象》曰：“家人嗃嗃”，未失也。“妇子嘻嘻”，失家节也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未失也”者，初虽悔厉，似失於猛，终无慢黩，故曰：“未失也”。“失家节”者，若纵其嘻嘻，初虽欢乐，终失家节也。</p><h2 id="六四-富家-大吉。-​" tabindex="-1">六四：富家，大吉。 ​ <a class="header-anchor" href="#六四-富家-大吉。-​" aria-label="Permalink to “六四：富家，大吉。 ​”">​</a></h2><p>王弼：能以其富顺而处位，故“大吉”也。若但能富其家，何足为大吉无体柔居巽，履得其位，明於家道，以近至尊，能富其家也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：富谓禄位昌盛也。六四体柔处巽，得位承五，能富其家者也。由其体巽承尊，长保禄位，吉之大者也，故曰“富家大吉”。</p><h3 id="《象》曰-富家-大吉-顺在位也。-​" tabindex="-1">《象》曰：“富家，大吉”，顺在位也。 ​ <a class="header-anchor" href="#《象》曰-富家-大吉-顺在位也。-​" aria-label="Permalink to “《象》曰：“富家，大吉”，顺在位也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“顺在位”者，所以致大吉，由顺承於君而在臣位，故不见黜夺也。</p><h2 id="九五-王假有家-勿恤-吉。-​" tabindex="-1">九五：王假有家，勿恤，吉。 ​ <a class="header-anchor" href="#九五-王假有家-勿恤-吉。-​" aria-label="Permalink to “九五：王假有家，勿恤，吉。 ​”">​</a></h2><p>王弼：假，至也。履正而应，处尊体巽，王至斯道，以有其家者也。居於尊位，而明於家道，则下莫不化矣。父父、子子、兄兄、弟弟、夫夫、妇妇，六亲和睦交相爱乐而家道正，“正家而天下定矣”。故“王假有家”，则勿恤而吉。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“王假有家”者，假，至也。九五履正而应，处尊体巽，是能以尊贵巽接於物，王至此道，以有其家，故曰“王假有家”也。“勿恤吉”者，居於尊位而明於家道，则在下莫不化之矣，不须忧恤而得吉也，故曰“勿恤吉”也。</p><h3 id="《象》曰-王假有家-交相爱也。-​" tabindex="-1">《象》曰：“王假有家”，交相爱也。 ​ <a class="header-anchor" href="#《象》曰-王假有家-交相爱也。-​" aria-label="Permalink to “《象》曰：“王假有家”，交相爱也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“交相爱也”者，王既明於家道，天下化之，“六亲和睦，交相爱乐”也。</p><h2 id="上九-有孚-威如-终吉。-​" tabindex="-1">上九：有孚，威如，终吉。 ​ <a class="header-anchor" href="#上九-有孚-威如-终吉。-​" aria-label="Permalink to “上九：有孚，威如，终吉。 ​”">​</a></h2><p>王弼：处家人之终，居家道之成，“刑于寡妻”，以著于外者也，故曰“有孚”。凡物以猛为本者则患在寡恩，以爱为本者则患在寡威，故家人之道尚威严也。家道可终，唯信与威。身得威敬，人亦如之。反之於身，则知施於人也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：上九处家人之终，家道大成，“刑于寡妻”，以著於外，信行天下，故曰“有孚”也。威被海内，故曰“威如”。威、信并立，上得终於家道，而吉从之，故曰“有孚威如终吉”也。</p><h3 id="《象》曰-威如-之吉-反身之谓也。-​" tabindex="-1">《象》曰：“威如”之吉，反身之谓也。 ​ <a class="header-anchor" href="#《象》曰-威如-之吉-反身之谓也。-​" aria-label="Permalink to “《象》曰：“威如”之吉，反身之谓也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“反身之谓”者，身得人敬则敬於人，明知身敬於人人亦敬已，反之於身则知施之於人，故曰“反身之谓”也。</p>',65)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
